public class TestSolution {static void check(long g,long e){if(g!=e)throw new AssertionError("got="+g+" expected="+e);}public static void main(String[] a){check(Solution.cheapestTrip(3,new int[][]{{0,1,10},{1,2,10},{0,2,25}}),12);check(Solution.cheapestTrip(4,new int[][]{{0,1,8},{1,3,8},{0,2,3},{2,3,20}}),12);check(Solution.cheapestTrip(2,new int[][]{}),-1);check(Solution.cheapestTrip(2,new int[][]{{0,1,1}}),0);check(Solution.cheapestTrip(4,new int[][]{{0,1,100},{0,2,2},{2,1,2},{1,3,10},{2,3,50}}),7);System.out.println("All tests passed.");}}
